use vstd::prelude::*;

verus! {

fn concatenate(a: Vec<f32>, b: Vec<f32>) -> (c: Vec<f32>)
    ensures
        c@.len() == a@.len() + b@.len(),
        forall|i: int|
            0 <= i && i < a@.len()
            ==> c@[i] == a@[i],
        forall|j: int|
            0 <= j && j < b@.len()
            ==> c@[a@.len() + j] == b@[j],
{
    let mut c: Vec<f32> = Vec::new();

    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            c@ == a@.subrange(0, i as int),
        decreases a.len() - i,
    {
        c.push(a[i]);
        i = i + 1;
    }

    let a_len_usize: usize = a.len();
    let a_len_int: int = a@.len();

    let mut j: usize = 0;
    while j < b.len()
        invariant
            j <= b.len(),
            c@ == a@ + b@.subrange(0, j as int),
            a@.len() == a_len_int,
            a.len() == a_len_usize,
        decreases b.len() - j,
    {
        c.push(b[j]);
        j = j + 1;
    }

    // At this point, c@ == a@ + b@.subrange(0, b@.len()) == a@ + b@
    c
}

} // verus!

